/* Project-scoped command center. Metrics represent current records, not invented trends. */
window.ProjectDashboard=(()=>{
 function model(data,today){
  const p=data.project,tasks=data.issues.filter(t=>t.projectId===p.id),open=tasks.filter(t=>t.status!=='Done'),done=tasks.length-open.length;
  const team=data.teams.find(t=>t.id===p.teamId),ids=new Set([p.managerId,...(p.memberIds||[]),...(team?.memberIds||[]),...tasks.map(t=>t.assigneeId)].filter(Boolean));
  const people=data.members.filter(m=>ids.has(m.id)),overdue=open.filter(t=>t.endDate<today),dueSoon=open.filter(t=>t.endDate>=today&&Planning.day(t.endDate)<=Planning.day(today)+7);
  const checkpoints=data.milestones.filter(m=>m.projectId===p.id).sort((a,b)=>(a.status==='Completed')-(b.status==='Completed')||a.date.localeCompare(b.date));
  const progress=Planning.progress(tasks);
  const elapsed=Math.max(0,Math.min(100,Math.round((Planning.day(today)-Planning.day(p.startDate))/(Math.max(1,Planning.day(p.endDate)-Planning.day(p.startDate)))*100)));
  return {p,tasks,open,done,team,people,overdue,dueSoon,checkpoints,progress,elapsed,
   health:!tasks.length?'Not started':overdue.length?'Needs attention':done===tasks.length?'Delivered':'On track',
   counts:Planning.statuses.map(status=>({status,count:tasks.filter(t=>t.status===status).length})),
   docs:data.documents.filter(d=>d.projectId===p.id&&!d.trashed),
   upcoming:data.events.filter(e=>e.projectId===p.id&&!e.cancelled&&e.endDate>=today).sort((a,b)=>(a.date+(a.time||'')).localeCompare(b.date+(b.time||''))),
   focus:[...open].sort((a,b)=>a.endDate.localeCompare(b.endDate)||a.name.localeCompare(b.name))};
 }
 function render(data,{today,date,avatar}){
  const m=model(data,today),p=m.p,empty=text=>`<p class="pd-empty">${text}</p>`,head=(name,action='')=>`<div class="pd-panel-head"><h2>${name}</h2>${action}</div>`;
  const action=(label,attr)=>`<button class="text-btn" ${attr}>${label}</button>`;
  const taskRows=rows=>rows.map(t=>`<tr><td><button class="task-title" data-bug-edit="${t.id}"><small>${esc(ProjectAPI.ticketKey(t))}</small>${esc(t.name)}</button></td><td>${esc(t.kind)}</td><td><span class="badge">${esc(t.status)}</span></td><td>${avatar(data.members.find(x=>x.id===t.assigneeId))} <span>${esc(data.members.find(x=>x.id===t.assigneeId)?.name||'Unassigned')}</span></td><td class="${t.endDate<today&&t.status!=='Done'?'pd-late':''}">${date(t.endDate)}</td></tr>`).join('');
  return `<div class="pd-command">
  <div class="pd-summary" aria-label="Project health summary">${[
   ['Delivery health',m.health,m.overdue.length?'Open tasks past their due date':'Based on current task deadlines'],['Tasks',m.tasks.length,'Total in this project'],['Completed',m.done,m.progress+'% overall progress'],['In progress',m.counts.find(x=>x.status==='In Progress').count,'Tasks underway'],['Overdue',m.overdue.length,'Open tasks past due'],['Due in 7 days',m.dueSoon.length,'Open tasks approaching due']
  ].map(([label,value,detail])=>`<div><span>${label}</span><strong class="${label==='Delivery health'?(m.overdue.length?'pd-late':'pd-good'):''}">${label==='Delivery health'?value:DashboardLinks.button(value,label,'tasks',label==='Due in 7 days'?m.dueSoon:DashboardLinks.tasksFor(label,m.tasks,today))}</strong><small>${detail}</small></div>`).join('')}</div>
  <section class="panel pd-issue-map"><div class="panel-heading"><div><h2>Time-Based Issue Map</h2><p>Timeline of this project's scheduled issues</p></div><div class="pd-map-controls"><div id="project-map-range" class="pd-periods" aria-label="Timeline period">${['Week','Month','Quarter'].map(range=>`<button data-project-map-range="${range}">${range}</button>`).join('')}</div><button class="secondary" data-project-gantt="${p.id}">Open Gantt</button></div></div><div id="project-timeline" class="timeline"></div><div class="chart-foot">${Planning.statuses.map(status=>`<span><i class="dot ${Planning.colors[status]}"></i> ${status}</span>`).join('')}</div></section>
  <div class="pd-grid">
   <section class="panel pd-panel">${head('Delivery progress',action('Open board',`data-project-board="${p.id}"`))}<p class="muted">Current task status · ${m.tasks.length} tasks</p><div class="pd-bars" role="img" aria-label="${esc(m.counts.map(x=>x.status+': '+x.count).join(', '))}">${m.counts.map(x=>`<div><b>${DashboardLinks.button(x.count,x.status+' tasks','tasks',m.tasks.filter(t=>t.status===x.status))}</b><div class="pd-bar-space"><i style="height:${x.count/Math.max(1,...m.counts.map(x=>x.count))*100}%" class="${Planning.colors[x.status]}"></i></div><small>${esc(x.status)}</small></div>`).join('')}</div><div class="pd-chart-foot"><strong>${m.progress}%</strong><span>overall progress · ${m.done} of ${m.tasks.length} tasks closed</span></div></section>
   <section class="panel pd-panel">${head('Schedule & completion',action('Open Gantt',`data-project-gantt="${p.id}"`))}<div class="pd-progress-ring" style="--progress:${m.progress}%" role="img" aria-label="${m.progress}% overall progress"><span><strong>${m.progress}%</strong><small>Overall progress</small></span></div><div class="pd-meter"><span>Schedule elapsed <b>${m.elapsed}%</b></span><div><i style="width:${m.elapsed}%"></i></div></div><p class="pd-date">${date(p.startDate)} → ${date(p.endDate)}</p><small class="muted">Calendar elapsed versus completed task count; not a workload estimate.</small></section>
   <section class="panel pd-panel">${head('Current project',action('Edit',`data-project-edit="${p.id}"`))}<p class="pd-key">${esc(ProjectAPI.projectKey(p))}</p><h3>${esc(p.name)}</h3><span class="badge">${esc(p.status)}</span><p class="pd-description">${esc(p.description||'Add a description to give the team context.')}</p><small class="muted">Project manager</small><div class="pd-owner">${avatar(data.members.find(x=>x.id===p.managerId))}<span>${esc(data.members.find(x=>x.id===p.managerId)?.name||'Unassigned')}</span></div><small class="muted">${esc(m.team?.name||'Project members')} · ${m.people.length} people</small><div class="member-stack pd-members">${m.people.map(avatar).join('')||'<span class="muted">No members yet</span>'}</div></section>
   <section class="panel pd-panel">${head('Milestones',action('+ Add',`data-project-milestone="${p.id}"`))}<div class="pd-list">${m.checkpoints.map(item=>`<button class="pd-list-item" data-milestone-edit="${item.id}"><strong>${esc(item.name)}</strong><span>${date(item.date)}<small class="${item.status!=='Completed'&&item.date<today?'pd-late':''}">${item.status==='Completed'?'Completed':item.date<today?'Overdue':'Upcoming'}</small></span></button>`).join('')||empty('No milestones yet. Add the next delivery checkpoint.')}</div></section>
   <section class="panel pd-panel">${head('Team workload')}<p class="muted">Open assignments in this project</p><div class="pd-list">${m.people.map(member=>{const assigned=m.tasks.filter(t=>t.assigneeId===member.id),active=assigned.filter(t=>t.status!=='Done');return `<div class="pd-person">${avatar(member)}<button class="text-btn" data-member-profile="${member.id}">${esc(member.name)}<small>${assigned.filter(t=>t.status==='Done').length} completed${member.active?'':' · Inactive'}</small></button><b>${active.length}<small>open</small></b></div>`}).join('')||empty('Assign members to see their workload.')}</div><p class="pd-date">${m.open.filter(t=>!t.assigneeId).length} open tasks unassigned</p></section>
   <section class="panel pd-panel">${head('Recent activity',action('Refresh','data-project-activity-refresh'))}<div id="project-activity" class="pd-list" aria-live="polite">Loading project activity…</div></section>
   <section class="panel pd-panel pd-wide">${head('Tasks needing attention',action('All tasks',`data-project-plan="${p.id}"`))}<p class="muted">Open tasks, ordered by due date</p><div class="bug-table-wrap"><table class="bug-table"><thead><tr><th>Ticket</th><th>Type</th><th>Status</th><th>Assignee</th><th>Due date</th></tr></thead><tbody>${taskRows(m.focus.slice(0,8))||'<tr><td colspan="5">No open tasks. Create a task to plan the next step.</td></tr>'}</tbody></table></div>${m.focus.length>8?`<p class="pd-date">Showing 8 of ${m.focus.length} open tasks.</p>`:''}</section>
   <section class="panel pd-panel">${head('Documents',action('Manage',`data-project-docs="${p.id}"`))}<div class="pd-list">${m.docs.slice(0,5).map(d=>`<button class="pd-list-item" data-doc-open="${d.id}"><strong>${esc(d.name)}</strong><small>${esc(d.category)} · ${d.kind==='file'?'File':'Note'}</small></button>`).join('')||empty('No project documents yet.')}</div></section>
   <section class="panel pd-panel">${head('Upcoming events',action('Calendar',`data-project-events="${p.id}"`))}<div class="pd-list">${m.upcoming.slice(0,5).map(e=>`<button class="pd-list-item" data-event-edit="${e.id}"><strong>${esc(e.title)}</strong><span>${date(e.date)}<small>${esc(e.type)} · ${e.allDay?'All day':esc(e.time)}</small></span></button>`).join('')||empty('No upcoming events.')}</div></section>
  </div></div>`;
 }
 return {model,render};
})();
